sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var infoPayload = JSON.parse(api.data.get_ops_user_data_1.output);
    var resultArr = [];
    for (var element in infoPayload) {
        if (element == "dl") {
            resultArr.push({
                "label": "Development Leader",
                "value": infoPayload[element]
            });
        }
        if (element == "coach") {
            resultArr.push({
                "label": "Coach",
                "value": infoPayload[element]
            });
        }
        if (element == "project") {
            resultArr.push({
                "label": "Project(s)",
                "value": infoPayload[element]
            });
        }
        if (element == "contact") {
            resultArr.push({
                "label": "Mobile Phone",
                "value": infoPayload[element]
            });
        }
        if (element == "email") {
            resultArr.push({
                "label": "Email Id",
                "value": infoPayload[element]
            });
        }
    }
    return resultArr;
}
